t.script:
// Define callback function immediately for Google Maps API
window.initMapCallback = function() {
    console.log('Google Maps API callback triggered');
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initMap);
    } else {
        initMap();
    }
};

// Route data from server
let routeData;
try {
    // Route data is already a JavaScript object from template
    routeData = ;
    console.log('Route data loaded:', routeData);
    console.log('Route data type:', typeof routeData);
    console.log('Route data length:', routeData ? routeData.length : 'undefined');
} catch (e) {
    console.error('Error loading route data:', e);
    alert('Error: Invalid route data format. Please try optimizing the route again.');
    routeData = []; // Set empty array instead of return
}

let map;
let routePolyline;
let markers = [];


function initMap() {
    console.log('Initializing route map with', routeData.length, 'points');
    console.log('Route data:', routeData);

    // Check if route data is valid
    if (!routeData || routeData.length === 0) {
        console.error('No valid route data available');
        document.getElementById('map').innerHTML = '<div style="padding: 20px; text-align: center; color: red;">Error: No route data available. Please optimize the route first.</div>';
        return;
    }

    // Check if Google Maps is loaded
    if (typeof google === 'undefined' || !google.maps) {
        console.error('Google Maps API not loaded');
        document.getElementById('map').innerHTML = '<div style="padding: 20px; text-align: center; color: red;">Error: Google Maps API not loaded</div>';
        return;
    }

    console.log('Google Maps API loaded successfully');

    // Create map centered on first point
    const firstPoint = routeData[0];
    const center = {
        lat: parseFloat(firstPoint.lat),
        lng: parseFloat(firstPoint.lng)
    };

    // Detect if mobile device
    const isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);

    map = new google.maps.Map(document.getElementById('map'), {
        zoom: 15,
        center: center,
        mapTypeId: 'roadmap',
        mapTypeControl: !isMobile,
        streetViewControl: !isMobile,
        fullscreenControl: true,
        zoomControl: true,
        gestureHandling: isMobile ? 'greedy' : 'cooperative',
        disableDefaultUI: isMobile
    });

    // Create route path coordinates
    const pathCoordinates = routeData.map(point => ({
        lat: parseFloat(point.lat),
        lng: parseFloat(point.lng)
    }));

    // Draw route polyline
    routePolyline = new google.maps.Polyline({
        path: pathCoordinates,
        geodesic: true,
        strokeColor: '#3b82f6',
        strokeOpacity: 0.8,
        strokeWeight: 4,
        map: map
    });

    // Add direction arrows
    const lineSymbol = {
        path: google.maps.SymbolPath.FORWARD_CLOSED_ARROW,
        scale: 3,
        strokeColor: '#1e40af',
    };

    routePolyline.setOptions({
        icons: [{
            icon: lineSymbol,
            offset: '50%',
            repeat: '100px'
        }]
    });

    // Add markers for each point
    const bounds = new google.maps.LatLngBounds();

    routeData.forEach((point, index) => {
        const position = {
            lat: parseFloat(point.lat),
            lng: parseFloat(point.lng)
        };

        // Determine marker color
        let markerColor = '#3b82f6'; // blue for regular points
        let markerLabel = String(index + 1);

        if (index === 0) {
            markerColor = '#10b981'; // green for start
            markerLabel = 'S';
        } else if (index === routeData.length - 1) {
            markerColor = '#ef4444'; // red for end
            markerLabel = 'E';
        }

        // Create custom marker
        const marker = new google.maps.Marker({
            position: position,
            map: map,
            label: {
                text: markerLabel,
                color: 'white',
                fontSize: '12px',
                fontWeight: 'bold'
            },
            icon: {
                path: google.maps.SymbolPath.CIRCLE,
                scale: 12,
                fillColor: markerColor,
                fillOpacity: 1,
                strokeColor: '#ffffff',
                strokeWeight: 2
            },
            title: point.name || 'Point ' + (index + 1)
        });

        // Create info window
        const infoContent = `
            <div style="padding: 10px;">
                <h3 style="margin: 0 0 8px 0;">${point.name || 'Point ' + (index + 1)}</h3>
                <p style="margin: 3px 0;"><strong>Order:</strong> ${index + 1}</p>
                ${point.code ? `<p style="margin: 3px 0;"><strong>Code:</strong> ${point.code}</p>` : ''}
                <p style="margin: 3px 0;"><strong>Coordinates:</strong> ${position.lat.toFixed(6)}, ${position.lng.toFixed(6)}</p>
            </div>
        `;

        const infoWindow = new google.maps.InfoWindow({
            content: infoContent
        });

        marker.addListener('click', () => {
            // Close all other info windows
            markers.forEach(m => {
                if (m.infoWindow) {
                    m.infoWindow.close();
                }
            });
            infoWindow.open(map, marker);
        });

        marker.infoWindow = infoWindow;
        markers.push(marker);
        bounds.extend(position);
    });

    // Fit map to show entire route
    if (routeData.length > 0) {
        map.fitBounds(bounds);

        // Adjust zoom for single point
        if (routeData.length === 1) {
            map.setZoom(16);
        }
    }

    console.log('Route map initialized successfully');
}

// Initialize when DOM is ready (fallback)
document.addEventListener('DOMContentLoaded', function() {
    console.log('DOM loaded, checking if map needs initialization...');

    // If callback hasn't been triggered after 5 seconds, try direct initialization
    setTimeout(() => {
        if (!map && typeof google !== 'undefined' && google.maps) {
            console.log('Fallback: Direct map initialization');
            initMap();
        } else if (!map) {
            console.error('Fallback: Google Maps still not available');
            document.getElementById('map').innerHTML = '<div style="padding: 20px; text-align: center; color: red;">Error: Google Maps failed to load. Please check your internet connection and try again.</div>';
        }
    }, 5000);
});
